package co.com.nequi.ticketing.model.order;

import java.util.Objects;
import java.util.UUID;

/**
 * Unique identifier of an order, generated by the server when the tickets are reserved.
 *
 * @param value the UUID that identifies the order
 */
public record OrderId(UUID value) {

    public OrderId {
        Objects.requireNonNull(value, "Order id value must not be null");
    }

    /**
     * Generates a new random identifier.
     *
     * @return a new identifier
     */
    public static OrderId newId() {
        return new OrderId(UUID.randomUUID());
    }
}
